package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name, input, want string
	}{
		{"empty", "", ""},
		{"unchanged", "KeepCase", "KeepCase"},
		{"spaces", "  Keep  Case  ", "Keep  Case"},
		{"ASCII whitespace", "\t\n\v\f\r Keep  Case \r\f\v\n\t", "Keep  Case"},
		{"Unicode boundaries", "\u00a0\u2003Keep  Case\u202f\u3000", "Keep  Case"},
		{"interior content", "\u2003MiXeD\t\u00a0\n世界\u2003Case\u3000", "MiXeD\t\u00a0\n世界\u2003Case"},
		{"whitespace only", "\t\u00a0\u2003\u202f\u3000\n", ""},
		{"non-whitespace boundaries", "\u200bKeep Case\ufeff", "\u200bKeep Case\ufeff"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.input); got != tt.want {
				t.Fatalf("NormalizeLabel(%q) = %q; want %q", tt.input, got, tt.want)
			}
		})
	}
}

